    END IF;
  END LOOP;

  -- The view: creator_coach_plan is the LAST column, and both client roles can
  -- still read the view.
  SELECT attname INTO v_last FROM pg_attribute
   WHERE attrelid = 'public.sessions_public'::regclass AND attnum > 0 AND NOT attisdropped
   ORDER BY attnum DESC LIMIT 1;
  IF v_last IS DISTINCT FROM 'creator_coach_plan' THEN
    RAISE EXCEPTION '219 ABORTED: the last column of sessions_public is %, not creator_coach_plan.', coalesce(v_last, '(none)');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_attribute
                  WHERE attrelid = 'public.sessions_public'::regclass
                    AND attname = 'partner_reviewed_at' AND NOT attisdropped) THEN
    RAISE EXCEPTION '219 ABORTED: sessions_public lost partner_reviewed_at.';
  END IF;
  IF NOT has_table_privilege('anon', 'public.sessions_public', 'SELECT')
     OR NOT has_table_privilege('authenticated', 'public.sessions_public', 'SELECT') THEN
    RAISE EXCEPTION '219 ABORTED: anon or authenticated can no longer read sessions_public; signed-out session pages would break.';
  END IF;

  RAISE NOTICE '219: eight coach_plan columns, server-only writes, coach_plan readable by signed-in users, creator_coach_plan on sessions_public.';
END $$;$guard$;

  k_coach uuid := gen_random_uuid();   -- buys Coach Pro through the webhook
  k_other uuid := gen_random_uuid();   -- another signed-in user, the reader
  k_ins   uuid := gen_random_uuid();   -- stays basico; the INSERT and E arms
  k_adm   uuid := gen_random_uuid();   -- a throwaway admin, the B7 actor
  k_sess  uuid := gen_random_uuid();   -- a throwaway open session by k_coach
  k_end   timestamptz := date_trunc('second', now() + interval '30 days');
  v_n integer; v_txt text; v_row record; v_id uuid;

  a1_state text := '(never ran)'; a1_ok boolean := false;
  a2_state text := '(never ran)'; a2_ok boolean := false;
  f5_state text := '(never ran)'; f5_ok boolean := false;
  b1_state text := '(never ran)'; b1_ok boolean := false;
  b2_state text := '(never ran)'; b2_ok boolean := false;
  b3_state text := '(never ran)'; b3_ok boolean := false;
  b4_state text := '(never ran)'; b4_ok boolean := false;
  b5_state text := '(never ran)'; b5_ok boolean := false;
  b6_state text := '(never ran)'; b6_ok boolean := false;
  b7_state text := '(never ran)'; b7_ok boolean := false;
  b8_state text := '(never ran)'; b8_ok boolean := false;
  b9_state text := '(never ran)'; b9_ok boolean := false;
  b10_state text := '(never ran)'; b10_ok boolean := false;
  b11_state text := '(never ran)'; b11_ok boolean := false;
  b12_state text := '(never ran)'; b12_ok boolean := false;
  b13_state text := '(never ran)'; b13_ok boolean := false;
  b14_state text := '(never ran)'; b14_ok boolean := false;
  b15_state text := '(never ran)'; b15_ok boolean := false;
  b16_state text := '(never ran)'; b16_ok boolean := false;
  b17_state text := '(never ran)'; b17_ok boolean := false;
  b18_state text := '(never ran)'; b18_ok boolean := false;
  b18_with text; b18_without text;
  d0_state text := '(never ran)'; d0_ok boolean := false;
  d1_state text := '(never ran)'; d1_ok boolean := false;
  d2_state text := '(never ran)'; d2_ok boolean := false;
  d3_state text := '(never ran)'; d3_ok boolean := false;
  d4_state text := '(never ran)'; d4_ok boolean := false;
  d5_state text := '(never ran)'; d5_ok boolean := false;
  d6_state text := '(never ran)'; d6_ok boolean := false;
  e1_state text := '(never ran)'; e1_ok boolean := false;
  f1_state text := '(never ran)'; f1_ok boolean := false;
  f2_state text := '(never ran)'; f2_ok boolean := false;
  f3_state text := '(never ran)'; f3_ok boolean := false;
  f4_state text := '(never ran)'; f4_ok boolean := false;
BEGIN

-- A1: the catalog, independently of the guard that already passed.
SELECT count(*) INTO v_n FROM pg_attribute
 WHERE attrelid = 'public.users'::regclass AND attnum > 0 AND NOT attisdropped AND attname LIKE 'coach\_plan%';
a1_state := v_n || ' coach_plan* columns, '
  || (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.users'::regclass
       AND conname LIKE 'users\_coach\_plan\_%' AND contype = 'c' AND convalidated) || ' validated CHECKs, trigger '
  || coalesce((SELECT CASE tgenabled WHEN 'O' THEN 'enabled' ELSE 'NOT enabled' END FROM pg_trigger
                WHERE tgrelid = 'public.users'::regclass AND tgname = 'users_coach_plan_guard'), 'ABSENT');
a1_ok := v_n = 8 AND a1_state LIKE '%4 validated CHECKs, trigger enabled';

-- A2: scaffolding. Four throwaway signups through the real auth path, one made
-- admin, and one open session hosted by the coach.
BEGIN
  INSERT INTO auth.users (id, email, created_at, raw_user_meta_data)
  VALUES (k_coach, 'reh-219-coach@example.com', now(), '{"name":"Reh Coach"}'::jsonb),
         (k_other, 'reh-219-other@example.com', now(), '{"name":"Reh Other"}'::jsonb),
         (k_ins,   'reh-219-ins@example.com',   now(), '{"name":"Reh Ins"}'::jsonb),
         (k_adm,   'reh-219-adm@example.com',   now(), '{"name":"Reh Admin"}'::jsonb);
  UPDATE public.users SET is_admin = true WHERE id = k_adm;
  INSERT INTO public.sessions (id, creator_id, title, sport, date, start_time, duration, location,
                               max_participants, join_policy)
  VALUES (k_sess, k_coach, 'Reh 219', 'running', current_date + 1, '07:00', 60, 'Reh park', 10, 'open');
  SELECT count(*) INTO v_n FROM public.users WHERE id IN (k_coach, k_other, k_ins, k_adm);
  a2_state := v_n || ' of 4 throwaway users rows created by handle_new_user; admin actor '
    || CASE WHEN public.is_app_admin_uid(k_adm) THEN 'is admin' ELSE 'NOT admin' END
    || '; session ' || CASE WHEN EXISTS (SELECT 1 FROM public.sessions WHERE id = k_sess) THEN 'created' ELSE 'MISSING' END;
  a2_ok := v_n = 4 AND public.is_app_admin_uid(k_adm) AND EXISTS (SELECT 1 FROM public.sessions WHERE id = k_sess);
EXCEPTION WHEN OTHERS THEN
  a2_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; a2_ok := false;
END;

-- F5: who is running this. CLAUDE.md: assert the role identity before any
-- arm whose meaning depends on it.
f5_state := 'current_user=' || current_user || ' session_user=' || session_user
  || ' auth.uid()=' || coalesce(auth.uid()::text, 'NULL');
f5_ok := auth.uid() IS NULL;

-- ── PART B ────────────────────────────────────────────────────────────────

-- B1: POSITIVE. A new signup starts on basico with nothing else set.
SELECT * INTO v_row FROM public.users WHERE id = k_ins;
b1_state := 'coach_plan=' || coalesce(v_row.coach_plan, 'NULL') || ', status/source/ids/dates all NULL='
  || (v_row.coach_plan_status IS NULL AND v_row.coach_plan_source IS NULL
      AND v_row.coach_plan_stripe_customer_id IS NULL AND v_row.coach_plan_stripe_subscription_id IS NULL
      AND v_row.coach_plan_current_period_end IS NULL AND v_row.coach_plan_granted_by IS NULL
      AND v_row.coach_plan_granted_at IS NULL)::text;
b1_ok := v_row.coach_plan = 'basico' AND b1_state LIKE '%all NULL=true';

-- B2: POSITIVE. The webhook's write after checkout.session.completed: service
-- role, no sub. Every column read back.
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  BEGIN
    UPDATE public.users
       SET coach_plan = 'pro', coach_plan_status = 'active', coach_plan_source = 'stripe',
           coach_plan_stripe_customer_id = 'cus_reh219coach', coach_plan_stripe_subscription_id = 'sub_reh219coach',
           coach_plan_current_period_end = k_end
     WHERE id = k_coach
    RETURNING id INTO v_id;
    b2_state := 'wrote ' || CASE WHEN v_id IS NULL THEN '0 rows' ELSE '1 row' END;
  EXCEPTION WHEN OTHERS THEN
    b2_state := 'REFUSED the webhook''s own write: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  SELECT * INTO v_row FROM public.users WHERE id = k_coach;
  b2_ok := v_id IS NOT NULL AND v_row.coach_plan = 'pro' AND v_row.coach_plan_status = 'active'
    AND v_row.coach_plan_source = 'stripe' AND v_row.coach_plan_stripe_customer_id = 'cus_reh219coach'
    AND v_row.coach_plan_stripe_subscription_id = 'sub_reh219coach' AND v_row.coach_plan_current_period_end = k_end;
  b2_state := b2_state || '; read back ' || CASE WHEN b2_ok THEN 'as written' ELSE 'WRONG' END;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b2_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b2_ok := false;
END;

-- B3: a basico OWNER, signed in, makes themselves Pro. Refused by the trigger
-- (matched on its text), and the plan is unchanged afterwards.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    UPDATE public.users SET coach_plan = 'pro', coach_plan_source = 'stripe' WHERE id = k_ins;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    b3_state := 'SUCCEEDED (' || v_n || ' rows) -- a user made themselves Pro';
  EXCEPTION WHEN OTHERS THEN
    b3_state := SQLSTATE || ' ' || SQLERRM;
    b3_ok := SQLSTATE = '42501' AND SQLERRM LIKE '%set by the server only%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b3_ok := b3_ok AND (SELECT coach_plan = 'basico' FROM public.users WHERE id = k_ins);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b3_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b3_ok := false;
END;

-- B4: POSITIVE, AND THE ONE THAT MATTERS MOST. updateUser's shape, as the owner
-- of a PAID row: a profile edit that does not touch the plan. Runs on every
-- sign-in (upsertUserProfile refreshes the profile). A guard that refused it
-- would break sign-in for every Pro coach.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_coach::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    UPDATE public.users SET name = 'Reh Coach Renamed' WHERE id = k_coach;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    b4_state := 'profile update wrote ' || v_n || ' row';
  EXCEPTION WHEN OTHERS THEN
    b4_state := 'REFUSED a profile update, so sign-in would break: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  SELECT * INTO v_row FROM public.users WHERE id = k_coach;
  b4_ok := b4_state = 'profile update wrote 1 row' AND v_row.name = 'Reh Coach Renamed'
    AND v_row.coach_plan = 'pro' AND v_row.coach_plan_current_period_end = k_end;
  b4_state := b4_state || '; name=' || coalesce(v_row.name, 'NULL') || ', plan intact='
    || (v_row.coach_plan = 'pro' AND v_row.coach_plan_current_period_end = k_end)::text;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b4_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b4_ok := false;
END;

-- B5: POSITIVE. insertMissingProfile's shape: the owner inserts their own
-- profile row with no plan columns. ON CONFLICT DO NOTHING because the row
-- exists; BEFORE INSERT triggers fire before the conflict is detected, so the
-- INSERT branch of the guard IS reached and must let defaults through.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    INSERT INTO public.users (id, name, email) VALUES (k_ins, 'Reh Ins', 'reh-219-ins@example.com')
    ON CONFLICT (id) DO NOTHING;
    b5_state := 'profile insert accepted';
  EXCEPTION WHEN OTHERS THEN
    b5_state := 'REFUSED a plain profile insert: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b5_ok := b5_state = 'profile insert accepted';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b5_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b5_ok := false;
END;

-- B6: a client INSERT carrying a plan is refused (the INSERT branch).
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    INSERT INTO public.users (id, name, email, coach_plan, coach_plan_source)
    VALUES (k_ins, 'Reh Ins', 'reh-219-ins@example.com', 'crecimiento', 'stripe')
    ON CONFLICT (id) DO NOTHING;
    b6_state := 'SUCCEEDED -- a client INSERT carried a plan past the trigger';
  EXCEPTION WHEN OTHERS THEN
    b6_state := SQLSTATE || ' ' || SQLERRM;
    b6_ok := SQLSTATE = '42501' AND SQLERRM LIKE '%set by the server only%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b6_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b6_ok := false;
END;

-- B7: a signed-in ADMIN is refused too; comps go through the server route.
-- RLS admits the admin to the row via "Admins can update any user", so the
-- refusal must be the trigger's.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_adm::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    UPDATE public.users SET coach_plan_current_period_end = k_end + interval '365 days' WHERE id = k_coach;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    b7_state := CASE WHEN v_n = 0 THEN 'UPDATE 0, no error: RLS filtered the row, so the admin path was NOT exercised'
                     ELSE 'SUCCEEDED -- an admin edited a coach plan from the client' END;
  EXCEPTION WHEN OTHERS THEN
    b7_state := SQLSTATE || ' ' || SQLERRM;
    b7_ok := SQLSTATE = '42501' AND SQLERRM LIKE '%set by the server only%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b7_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b7_ok := false;
END;

-- B8: POSITIVE. The admin comp route's write: service role, embajador / comp,
-- granted_by and granted_at recorded, no Stripe ids.
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  BEGIN
    UPDATE public.users
       SET coach_plan = 'embajador', coach_plan_status = 'active', coach_plan_source = 'comp',
           coach_plan_granted_by = k_adm, coach_plan_granted_at = now()
     WHERE id = k_other
    RETURNING id INTO v_id;
    b8_state := 'wrote ' || CASE WHEN v_id IS NULL THEN '0 rows' ELSE '1 row' END;
  EXCEPTION WHEN OTHERS THEN
    b8_state := 'REFUSED the comp route''s write: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  SELECT * INTO v_row FROM public.users WHERE id = k_other;
  b8_ok := v_id IS NOT NULL AND v_row.coach_plan = 'embajador' AND v_row.coach_plan_source = 'comp'
    AND v_row.coach_plan_granted_by = k_adm AND v_row.coach_plan_granted_at IS NOT NULL;
  b8_state := b8_state || '; read back ' || CASE WHEN b8_ok THEN 'as written' ELSE 'WRONG' END;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b8_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b8_ok := false;
END;

-- B9: embajador sold through Stripe is refused (users_coach_plan_consistent).
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  BEGIN
    UPDATE public.users SET coach_plan = 'embajador', coach_plan_source = 'stripe' WHERE id = k_ins;
    b9_state := 'SUCCEEDED -- embajador with source stripe';
  EXCEPTION WHEN OTHERS THEN
    b9_state := SQLSTATE || ' ' || SQLERRM;
    b9_ok := SQLSTATE = '23514' AND SQLERRM LIKE '%users_coach_plan_consistent%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b9_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b9_ok := false;
END;

-- B10: a plan that does not exist is refused (users_coach_plan_values).
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  BEGIN
    UPDATE public.users SET coach_plan = 'platinum', coach_plan_source = 'stripe' WHERE id = k_ins;
    b10_state := 'SUCCEEDED -- an unknown plan was stored';
  EXCEPTION WHEN OTHERS THEN
    b10_state := SQLSTATE || ' ' || SQLERRM;
    b10_ok := SQLSTATE = '23514' AND SQLERRM LIKE '%users_coach_plan_values%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b10_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b10_ok := false;
END;

-- B11: a second account cannot take the coach's Stripe customer id.
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  BEGIN
    UPDATE public.users SET coach_plan_stripe_customer_id = 'cus_reh219coach' WHERE id = k_ins;
    b11_state := 'SUCCEEDED -- two accounts share one coach-plan customer';
  EXCEPTION WHEN OTHERS THEN
    b11_state := SQLSTATE || ' ' || SQLERRM;
    b11_ok := SQLSTATE = '23505' AND SQLERRM LIKE '%users_coach_plan_stripe_customer_id_key%';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b11_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b11_ok := false;
END;

-- B12: POSITIVE. A signed-in user reads ANOTHER user's coach_plan: the badge.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    SELECT coach_plan INTO v_txt FROM public.users WHERE id = k_coach;
    b12_state := 'read coach_plan=' || coalesce(v_txt, 'NULL');
  EXCEPTION WHEN OTHERS THEN
    b12_state := 'REFUSED the badge read: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b12_ok := b12_state = 'read coach_plan=pro';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b12_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b12_ok := false;
END;

-- B13: a signed-in user CANNOT read another coach's billing state.
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    SELECT coach_plan_current_period_end::text INTO v_txt FROM public.users WHERE id = k_coach;
    b13_state := 'READ another coach''s renewal date: ' || coalesce(v_txt, 'NULL');
  EXCEPTION WHEN OTHERS THEN
    b13_state := SQLSTATE || ' ' || SQLERRM;
    b13_ok := SQLSTATE = '42501';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b13_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b13_ok := false;
END;

-- B14: anon cannot read users.coach_plan directly (signed-out reads go
-- through sessions_public).
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"anon"}', true);
  SET LOCAL ROLE anon;
  BEGIN
    SELECT coach_plan INTO v_txt FROM public.users WHERE id = k_coach;
    b14_state := 'anon READ users.coach_plan=' || coalesce(v_txt, 'NULL');
  EXCEPTION WHEN OTHERS THEN
    b14_state := SQLSTATE || ' ' || SQLERRM;
    b14_ok := SQLSTATE = '42501';
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b14_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b14_ok := false;
END;

-- B15: POSITIVE. anon reads the coach's session through sessions_public and
-- sees creator_coach_plan = pro, the signed-out badge.
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"anon"}', true);
  SET LOCAL ROLE anon;
  BEGIN
    SELECT creator_coach_plan INTO v_txt FROM public.sessions_public WHERE id = k_sess;
    b15_state := 'anon read creator_coach_plan=' || coalesce(v_txt, 'NULL');
  EXCEPTION WHEN OTHERS THEN
    b15_state := 'REFUSED the signed-out read: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b15_ok := b15_state = 'anon read creator_coach_plan=pro';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b15_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b15_ok := false;
END;

-- B16: the view kept every column in place and appended exactly one, and lost
-- or gained no row other than the throwaway session.
DECLARE
  v_before text; v_after text; v_rows_before bigint; v_rows_after bigint;
BEGIN
  SELECT view_cols, view_rows INTO v_before, v_rows_before FROM reh_premise;
  SELECT string_agg(attname, ',' ORDER BY attnum) INTO v_after FROM pg_attribute
   WHERE attrelid = 'public.sessions_public'::regclass AND attnum > 0 AND NOT attisdropped;
  SELECT count(*) INTO v_rows_after FROM public.sessions_public WHERE id <> k_sess;
  b16_state := 'columns ' || CASE WHEN v_after = v_before || ',creator_coach_plan' THEN 'before + creator_coach_plan'
                                  ELSE 'CHANGED: ' || coalesce(v_after, 'NULL') END
    || '; rows ' || v_rows_before || ' -> ' || v_rows_after;
  b16_ok := v_after = v_before || ',creator_coach_plan' AND v_rows_after = v_rows_before;
END;

-- B17: the view's creator_coach_plan agrees with users.coach_plan on every row.
SELECT count(*) INTO v_n FROM public.sessions_public v JOIN public.users u ON u.id = v.creator_id
 WHERE v.creator_coach_plan IS DISTINCT FROM u.coach_plan;
b17_state := v_n || ' rows disagree';
b17_ok := v_n = 0;

-- B18: upsertUserProfile's older full shape, email included, with and without
-- 219's trigger. PASS iff the outcome is identical: 219 must not change what
-- this statement does, whatever that is (214's B11 found it may be refused by
-- the email grant, independently of any trigger).
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_coach::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    INSERT INTO public.users (id, name, email) VALUES (k_coach, 'Reh Coach', 'reh-219-coach@example.com')
    ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email;
    b18_with := 'succeeded';
  EXCEPTION WHEN OTHERS THEN
    b18_with := SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  BEGIN
    DROP TRIGGER users_coach_plan_guard ON public.users;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', k_coach::text, 'role', 'authenticated')::text, true);
    SET LOCAL ROLE authenticated;
    BEGIN
      INSERT INTO public.users (id, name, email) VALUES (k_coach, 'Reh Coach', 'reh-219-coach@example.com')
      ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email;
      b18_without := 'succeeded';
    EXCEPTION WHEN OTHERS THEN
      b18_without := SQLSTATE || ' ' || SQLERRM;
    END;
    RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
    RAISE EXCEPTION 'B18_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
    IF SQLERRM <> 'B18_ROLLBACK' THEN b18_without := 'scaffolding failed: ' || SQLERRM; END IF;
  END;
  b18_state := 'with 219: ' || coalesce(b18_with, '?') || ' | without: ' || coalesce(b18_without, '?');
  b18_ok := b18_with IS NOT NULL AND b18_with = b18_without;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  b18_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM; b18_ok := false;
END;

-- ── PART D: the migration's guard, unmutated and against six mutations ─────
-- Each mutation asserts it LANDED before the guard's answer is read, and every
-- arm ends in an exception so the subtransaction rolls the mutation back.

-- D0: POSITIVE. The guard passes on the real end state (with B's rows in it).
BEGIN
  EXECUTE v_guard;
  d0_state := 'guard passed on the migrated schema'; d0_ok := true;
EXCEPTION WHEN OTHERS THEN
  d0_state := 'guard REFUSED the real end state: ' || SQLERRM; d0_ok := false;
END;

-- D1: a client SELECT grant on a billing column.
BEGIN
  GRANT SELECT (coach_plan_stripe_customer_id) ON public.users TO authenticated;
  IF NOT has_column_privilege('authenticated', 'public.users', 'coach_plan_stripe_customer_id', 'SELECT') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d1_state := SQLERRM; d1_ok := SQLERRM LIKE '219 ABORTED: a client role can SELECT users.coach_plan_stripe_customer_id%';
END;

-- D2: the trigger disabled.
BEGIN
  ALTER TABLE public.users DISABLE TRIGGER users_coach_plan_guard;
  IF (SELECT tgenabled FROM pg_trigger WHERE tgrelid = 'public.users'::regclass
        AND tgname = 'users_coach_plan_guard') <> 'D' THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d2_state := SQLERRM; d2_ok := SQLERRM LIKE '219 ABORTED: users_coach_plan_guard is not an enabled%';
END;

-- D3: the consistency CHECK dropped.
BEGIN
  ALTER TABLE public.users DROP CONSTRAINT users_coach_plan_consistent;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.users'::regclass
              AND conname = 'users_coach_plan_consistent') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d3_state := SQLERRM; d3_ok := SQLERRM LIKE '219 ABORTED: CHECK users_coach_plan_consistent is missing%';
END;

-- D4: the badge read taken away from signed-in users.
BEGIN
  REVOKE SELECT (coach_plan) ON public.users FROM authenticated;
  IF has_column_privilege('authenticated', 'public.users', 'coach_plan', 'SELECT') THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d4_state := SQLERRM; d4_ok := SQLERRM LIKE '219 ABORTED: authenticated cannot SELECT users.coach_plan%';
END;

-- D5: the unique customer index dropped.
BEGIN
  DROP INDEX public.users_coach_plan_stripe_customer_id_key;
  IF to_regclass('public.users_coach_plan_stripe_customer_id_key') IS NOT NULL THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d5_state := SQLERRM; d5_ok := SQLERRM LIKE '219 ABORTED: users_coach_plan_stripe_customer_id_key is missing%';
END;

-- D6: the trigger recreated as BEFORE UPDATE only, so a client INSERT escapes.
BEGIN
  DROP TRIGGER users_coach_plan_guard ON public.users;
  CREATE TRIGGER users_coach_plan_guard BEFORE UPDATE ON public.users
    FOR EACH ROW EXECUTE FUNCTION public.guard_coach_plan();
  IF (SELECT tgtype & 4 FROM pg_trigger WHERE tgrelid = 'public.users'::regclass
        AND tgname = 'users_coach_plan_guard') <> 0 THEN
    RAISE EXCEPTION 'MUTATION_DID_NOT_LAND';
  END IF;
  EXECUTE v_guard;
  RAISE EXCEPTION 'GUARD_DID_NOT_FIRE';
EXCEPTION WHEN OTHERS THEN
  d6_state := SQLERRM; d6_ok := SQLERRM LIKE '219 ABORTED: users_coach_plan_guard is not an enabled%';
END;

-- ── PART E: the bug reverted ───────────────────────────────────────────────
-- Without the trigger, can an ordinary signed-in user make themselves Pro? If
-- YES, the trigger is the only control and the migration's premise holds. If
-- NO, something else already blocks it and the header is wrong about why the
-- trigger exists.
BEGIN
  DROP TRIGGER users_coach_plan_guard ON public.users;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k_ins::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    UPDATE public.users SET coach_plan = 'pro', coach_plan_status = 'active', coach_plan_source = 'stripe'
     WHERE id = k_ins;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    e1_state := 'without the trigger, the owner made themselves Pro on ' || v_n || ' row(s)';
    e1_ok := v_n = 1;
  EXCEPTION WHEN OTHERS THEN
    e1_state := 'without the trigger the write was STILL refused: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  RAISE EXCEPTION 'E1_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  IF SQLERRM <> 'E1_ROLLBACK' THEN e1_state := 'scaffolding failed: ' || SQLERRM; e1_ok := false; END IF;
END;

-- ── PART F: premises and baseline ─────────────────────────────────────────
f1_state := 'has_table_privilege(authenticated, users, UPDATE) = '
  || has_table_privilege('authenticated', 'public.users', 'UPDATE')::text;
f1_ok := has_table_privilege('authenticated', 'public.users', 'UPDATE');

f2_state := 'has_table_privilege(authenticated, users, INSERT) = '
  || has_table_privilege('authenticated', 'public.users', 'INSERT')::text;
f2_ok := has_table_privilege('authenticated', 'public.users', 'INSERT');

BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', true);
  SET LOCAL ROLE service_role;
  v_txt := coalesce(auth.uid()::text, 'NULL');
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  f3_state := 'auth.uid() under the service role''s claims = ' || v_txt;
  f3_ok := v_txt = 'NULL';
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  f3_state := SQLSTATE || ' ' || SQLERRM; f3_ok := false;
END;

DECLARE
  f4_real integer; f4_basico integer;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE coach_plan = 'basico' AND coach_plan_source IS NULL
                                      AND coach_plan_stripe_customer_id IS NULL)
    INTO f4_real, f4_basico
    FROM public.users WHERE id NOT IN (k_coach, k_other, k_ins, k_adm);
  f4_state := f4_real || ' real accounts, ' || f4_basico || ' on basico with nothing else set (must be all)';
  f4_ok := f4_real = f4_basico;
END;

INSERT INTO reh_probe VALUES
  (1,  'A1 eight columns, four validated CHECKs, the trigger enabled', a1_state, a1_ok),
  (2,  'A2 SCAFFOLDING: four throwaway signups via handle_new_user, an admin, a session', a2_state, a2_ok),
  (3,  'F5 IDENTITY: who runs this, and auth.uid() is NULL outside the arms', f5_state, f5_ok),
  (4,  'B1 POSITIVE: a new signup starts on basico with nothing else set', b1_state, b1_ok),
  (5,  'B2 POSITIVE: the webhook''s write (service role), every column read back', b2_state, b2_ok),
  (6,  'B3 a basico owner cannot make themselves Pro (trigger, by message)', b3_state, b3_ok),
  (7,  'B4 POSITIVE: a Pro coach''s profile update still works, plan intact', b4_state, b4_ok),
  (8,  'B5 POSITIVE: a plain profile INSERT by the owner still works', b5_state, b5_ok),
  (9,  'B6 a client INSERT carrying a plan is refused (INSERT branch)', b6_state, b6_ok),
  (10, 'B7 a signed-in ADMIN cannot edit a plan from the client either', b7_state, b7_ok),
  (11, 'B8 POSITIVE: the admin comp route''s write (embajador / comp)', b8_state, b8_ok),
  (12, 'B9 embajador with source stripe is refused', b9_state, b9_ok),
  (13, 'B10 an unknown plan value is refused', b10_state, b10_ok),
  (14, 'B11 two accounts cannot share a coach-plan Stripe customer', b11_state, b11_ok),
  (15, 'B12 POSITIVE: a signed-in user reads another user''s coach_plan', b12_state, b12_ok),
  (16, 'B13 a signed-in user cannot read another coach''s billing columns', b13_state, b13_ok),
  (17, 'B14 anon cannot read users.coach_plan directly', b14_state, b14_ok),
  (18, 'B15 POSITIVE: anon reads creator_coach_plan through sessions_public', b15_state, b15_ok),
  (19, 'B16 sessions_public: every column in place, one appended, same rows', b16_state, b16_ok),
  (20, 'B17 creator_coach_plan agrees with users.coach_plan on every row', b17_state, b17_ok),
  (21, 'B18 219 does not change what the full profile upsert (with email) does', b18_state, b18_ok),
  (22, 'D0 POSITIVE: the migration''s guard passes on the real end state', d0_state, d0_ok),
  (23, 'D1 guard fires on a client SELECT grant on a billing column', d1_state, d1_ok),
  (24, 'D2 guard fires on a disabled trigger', d2_state, d2_ok),
  (25, 'D3 guard fires on a dropped consistency CHECK', d3_state, d3_ok),
  (26, 'D4 guard fires when signed-in users lose the coach_plan read', d4_state, d4_ok),
  (27, 'D5 guard fires on a dropped unique customer index', d5_state, d5_ok),
  (28, 'D6 guard fires on an UPDATE-only trigger', d6_state, d6_ok),
  (29, 'E1 PREMISE: without the trigger, the owner CAN make themselves Pro', e1_state, e1_ok),
  (30, 'F1 PREMISE: authenticated holds table-level UPDATE on users', f1_state, f1_ok),
  (31, 'F2 PREMISE: authenticated holds INSERT on users', f2_state, f2_ok),
  (32, 'F3 PREMISE: the service role''s claims give auth.uid() = NULL', f3_state, f3_ok),
  (33, 'F4 BASELINE: every real account starts on basico with nothing else set', f4_state, f4_ok);

END $outer$;

-- The one result set for the transaction. Every row must read PASS. 33 of 33.
SELECT seq, CASE WHEN coalesce(passed, false) THEN 'PASS' ELSE 'FAIL' END AS result, check_name,
       coalesce(detail, '(probe row missing)') AS detail
FROM reh_probe ORDER BY seq;

ROLLBACK;

-- ══════════════════════════════════════════════════════════════════════════
-- PART G: nothing escaped.
--
-- RUN THIS AS ITS OWN STATEMENT, AFTER THE ROLLBACK ABOVE HAS ENDED. A check
-- inside the transaction would read a database where the migration IS applied
-- and could not observe whether it escaped.
--
-- Expected BEFORE apply: no coach_plan* columns, no guard function or trigger,
-- no creator_coach_plan on sessions_public, no reh-219 account or session,
-- 219 not recorded.
-- ══════════════════════════════════════════════════════════════════════════

SELECT t.seq, CASE WHEN t.passed THEN 'PASS' ELSE 'FAIL' END AS result, t.check_name, t.detail
FROM (VALUES
  (1, 'G1 no coach_plan* column is on the live users table',
      (SELECT coalesce(string_agg(attname, ', ' ORDER BY attname), '(none, as expected)') FROM pg_attribute
        WHERE attrelid = 'public.users'::regclass AND attnum > 0 AND NOT attisdropped AND attname LIKE 'coach\_plan%'),
      (SELECT count(*) FROM pg_attribute
        WHERE attrelid = 'public.users'::regclass AND attnum > 0 AND NOT attisdropped AND attname LIKE 'coach\_plan%') = 0),
  (2, 'G2 no guard function and no guard trigger',
      coalesce(to_regprocedure('public.guard_coach_plan()')::text, '(no function)') || ', '
      || (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'public.users'::regclass
            AND tgname = 'users_coach_plan_guard')::text || ' triggers',
      to_regprocedure('public.guard_coach_plan()') IS NULL
      AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.users'::regclass
                        AND tgname = 'users_coach_plan_guard')),
  (3, 'G3 sessions_public has no creator_coach_plan',
      (SELECT attname FROM pg_attribute WHERE attrelid = 'public.sessions_public'::regclass
         AND attnum > 0 AND NOT attisdropped ORDER BY attnum DESC LIMIT 1) || ' is the last column',
      NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public.sessions_public'::regclass
                    AND attname = 'creator_coach_plan')),
  (4, 'G4 no rehearsal account or session escaped',
      (SELECT count(*) FROM auth.users WHERE email LIKE 'reh-219-%')::text || ' auth, '
      || (SELECT count(*) FROM public.users WHERE email LIKE 'reh-219-%')::text || ' public, '
      || (SELECT count(*) FROM public.sessions WHERE title = 'Reh 219')::text || ' sessions',
      (SELECT count(*) FROM auth.users WHERE email LIKE 'reh-219-%') = 0
      AND (SELECT count(*) FROM public.users WHERE email LIKE 'reh-219-%') = 0
      AND (SELECT count(*) FROM public.sessions WHERE title = 'Reh 219') = 0),
  (5, 'G5 219 is NOT recorded as applied',
      (SELECT coalesce(string_agg(migration, ', '), '(not recorded, as expected)')
         FROM public.migrations_applied WHERE migration LIKE '219%'),
      (SELECT count(*) FROM public.migrations_applied WHERE migration LIKE '219%') = 0)
) AS t(seq, check_name, detail, passed)
ORDER BY t.seq;
